The bird known for its ability to repeat what you say is the **parrot**.

Here are the unit tests for the `sort_list` function using Python's built-in `unittest` framework:

```python
import unittest

def sort_list(num_list):
    return sorted(num_list)

class TestSortList(unittest.TestCase):
    """Unit tests for the sort_list function."""

    def test_sorted_list(self):
        """Test that a list of numbers is sorted in ascending order."""
        self.assertEqual(sort_list([3, 1, 2]), [1, 2, 3])

    def test_already_sorted_list(self):
        """Test that an already sorted list remains unchanged."""
        self.assertEqual(sort_list([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_reverse_sorted_list(self):
        """Test that a reverse sorted list is sorted correctly."""
        self.assertEqual(sort_list([5, 4, 3, 2, 1]), [1, 2, 3, 4, 5])

    def test_single_element_list(self):
        """Test that a list with a single element returns that element."""
        self.assertEqual(sort_list([10]), [10])

    def test_empty_list(self):
        """Test that an empty list returns an empty list."""
        self.assertEqual(sort_list([]), [])

    def test_list_with_negative_numbers(self):
        """Test that negative numbers are handled correctly."""
        self.assertEqual(sort_list([-1, -5, 3, 0, -2]), [-5, -2, -1, 0, 3])

    def test_list_with_duplicates(self):
        """Test that duplicate numbers are preserved in the sorted list."""
        self.assertEqual(sort_list([3, 1, 3, 2, 1]), [1, 1, 2, 3, 3])

if __name__ == '__main__':
    unittest.main()
```
